        if (!(c->flags & SWS_FULL_CHR_H_INT)) {

            switch (c->dstFormat) {

            case PIX_FMT_RGB32:

                c->yuv2packed1 = RENAME(yuv2rgb32_1);

                c->yuv2packed2 = RENAME(yuv2rgb32_2);

