#if !COMPILE_TEMPLATE_MMX2

    switch(srcFormat) {

        case PIX_FMT_YUYV422  : c->chrToYV12 = RENAME(yuy2ToUV); break;

        case PIX_FMT_UYVY422  : c->chrToYV12 = RENAME(uyvyToUV); break;

