    g_assert_cmphex(isa_inw(test, 0xe2), ==, 0x8765);

    g_assert_cmphex(isa_inw(test, 0xe0), ==, 0x4322);

    g_assert_cmphex(isa_inb(test, 0xe3), ==, 0x87);

