static void residual_interp(int16_t *buf, int16_t *out, int lag,

                            int gain, int *rseed)

{

    int i;

    if (lag) { /* Voiced */

        int16_t *vector_ptr = buf + PITCH_MAX;

        /* Attenuate */

        for (i = 0; i < lag; i++)

            out[i] = vector_ptr[i - lag] * 3 >> 2;

        av_memcpy_backptr((uint8_t*)(out + lag), lag * sizeof(*out),

                          (FRAME_LEN - lag) * sizeof(*out));

    } else {  /* Unvoiced */

        for (i = 0; i < FRAME_LEN; i++) {

            *rseed = *rseed * 521 + 259;

            out[i] = gain * *rseed >> 15;

        }

        memset(buf, 0, (FRAME_LEN + PITCH_MAX) * sizeof(*buf));

    }

}
,1,ffmpeg,f9018a7aa9134752d3d4549077b2e24f

void bdrv_drain_all(void)

{

    /* Always run first iteration so any pending completion BHs run */

    bool busy = true;

    BlockDriverState *bs;



    while (busy) {

        /* FIXME: We do not have timer support here, so this is effectively

         * a busy wait.

         */

        QTAILQ_FOREACH(bs, &bdrv_states, list) {

            if (bdrv_start_throttled_reqs(bs)) {

                busy = true;

            }

        }



        busy = bdrv_requests_pending_all();

        busy |= aio_poll(qemu_get_aio_context(), busy);

    }

}
,1,qemu,31cc7f77bba8bb934a37867a10f277f9

int net_init_socket(const Netdev *netdev, const char *name,

                    NetClientState *peer, Error **errp)

{

    /* FIXME error_setg(errp, ...) on failure */

    Error *err = NULL;

    const NetdevSocketOptions *sock;



    assert(netdev->type == NET_CLIENT_DRIVER_SOCKET);

    sock = &netdev->u.socket;



    if (sock->has_fd + sock->has_listen + sock->has_connect + sock->has_mcast +

        sock->has_udp != 1) {

        error_report("exactly one of fd=, listen=, connect=, mcast= or udp="

                     " is required");

        return -1;

    }



    if (sock->has_localaddr && !sock->has_mcast && !sock->has_udp) {

        error_report("localaddr= is only valid with mcast= or udp=");

        return -1;

    }



    if (sock->has_fd) {

        int fd;



        fd = monitor_fd_param(cur_mon, sock->fd, &err);

        if (fd == -1) {

            error_report_err(err);

            return -1;

        }

        qemu_set_nonblock(fd);

        if (!net_socket_fd_init(peer, "socket", name, fd, 1)) {

            return -1;

        }

        return 0;

    }



    if (sock->has_listen) {

        if (net_socket_listen_init(peer, "socket", name, sock->listen) == -1) {

            return -1;

        }

        return 0;

    }



    if (sock->has_connect) {

        if (net_socket_connect_init(peer, "socket", name, sock->connect) ==

            -1) {

            return -1;

        }

        return 0;

    }



    if (sock->has_mcast) {

        /* if sock->localaddr is missing, it has been initialized to "all bits

         * zero" */

        if (net_socket_mcast_init(peer, "socket", name, sock->mcast,

            sock->localaddr) == -1) {

            return -1;

        }

        return 0;

    }



    assert(sock->has_udp);

    if (!sock->has_localaddr) {

        error_report("localaddr= is mandatory with udp=");

        return -1;

    }

    if (net_socket_udp_init(peer, "socket", name, sock->udp, sock->localaddr) ==

        -1) {

        return -1;

    }

    return 0;

}
