            av_free_packet(pkt);

            return CHUNK_EOF;




        avio_seek(pb, s->video_chunk_offset, SEEK_SET);

        s->video_chunk_offset = 0;



        if (avio_read(pb, pkt->data + s->decode_map_chunk_size,

            s->video_chunk_size) != s->video_chunk_size) {

