static int dvvideo_decode_frame(AVCodecContext *avctx, void *data,

                                int *got_frame, AVPacket *avpkt)

{

    uint8_t *buf = avpkt->data;

    int buf_size = avpkt->size;

    DVVideoContext *s = avctx->priv_data;

    const uint8_t *vsc_pack;

    int apt, is16_9, ret;

    const AVDVProfile *sys;



    sys = av_dv_frame_profile(s->sys, buf, buf_size);

    if (!sys || buf_size < sys->frame_size) {

        av_log(avctx, AV_LOG_ERROR, "could not find dv frame profile\n");

        return -1; /* NOTE: we only accept several full frames */

    }



    if (sys != s->sys) {

        ret = ff_dv_init_dynamic_tables(s, sys);

        if (ret < 0) {

            av_log(avctx, AV_LOG_ERROR, "Error initializing the work tables.\n");

            return ret;

        }

        s->sys = sys;

    }



    s->frame            = data;

    s->frame->key_frame = 1;

    s->frame->pict_type = AV_PICTURE_TYPE_I;

    avctx->pix_fmt      = s->sys->pix_fmt;

    avctx->framerate    = av_inv_q(s->sys->time_base);



    ret = ff_set_dimensions(avctx, s->sys->width, s->sys->height);

    if (ret < 0)

        return ret;



    /* Determine the codec's sample_aspect ratio from the packet */

    vsc_pack = buf + 80 * 5 + 48 + 5;

    if (*vsc_pack == dv_video_control) {

        apt    = buf[4] & 0x07;

        is16_9 = (vsc_pack && ((vsc_pack[2] & 0x07) == 0x02 ||

                               (!apt && (vsc_pack[2] & 0x07) == 0x07)));

        ff_set_sar(avctx, s->sys->sar[is16_9]);

    }



    if (ff_get_buffer(avctx, s->frame, 0) < 0) {

        av_log(avctx, AV_LOG_ERROR, "get_buffer() failed\n");

        return -1;

    }

    s->frame->interlaced_frame = 1;

    s->frame->top_field_first  = 0;



    s->buf = buf;

    avctx->execute(avctx, dv_decode_video_segment, s->work_chunks, NULL,

                   dv_work_pool_size(s->sys), sizeof(DVwork_chunk));



    emms_c();



    /* return image */

    *got_frame = 1;



    return s->sys->frame_size;

}
,0,ffmpeg,be65f1eed0d4e7ea925de5ae33ca6e2d

static void disas_ldst_pair(DisasContext *s, uint32_t insn)

{

    int rt = extract32(insn, 0, 5);

    int rn = extract32(insn, 5, 5);

    int rt2 = extract32(insn, 10, 5);

    int64_t offset = sextract32(insn, 15, 7);

    int index = extract32(insn, 23, 2);

    bool is_vector = extract32(insn, 26, 1);

    bool is_load = extract32(insn, 22, 1);

    int opc = extract32(insn, 30, 2);



    bool is_signed = false;

    bool postindex = false;

    bool wback = false;



    TCGv_i64 tcg_addr; /* calculated address */

    int size;



    if (opc == 3) {

        unallocated_encoding(s);

        return;

    }



    if (is_vector) {

        size = 2 + opc;

    } else {

        size = 2 + extract32(opc, 1, 1);

        is_signed = extract32(opc, 0, 1);

        if (!is_load && is_signed) {

            unallocated_encoding(s);

            return;

        }

    }



    switch (index) {

    case 1: /* post-index */

        postindex = true;

        wback = true;

        break;

    case 0:

        /* signed offset with "non-temporal" hint. Since we don't emulate

         * caches we don't care about hints to the cache system about

         * data access patterns, and handle this identically to plain

         * signed offset.

         */

        if (is_signed) {

            /* There is no non-temporal-hint version of LDPSW */

            unallocated_encoding(s);

            return;

        }

        postindex = false;

        break;

    case 2: /* signed offset, rn not updated */

        postindex = false;

        break;

    case 3: /* pre-index */

        postindex = false;

        wback = true;

        break;

    }



    if (is_vector && !fp_access_check(s)) {

        return;

    }



    offset <<= size;



    if (rn == 31) {

        gen_check_sp_alignment(s);

    }



    tcg_addr = read_cpu_reg_sp(s, rn, 1);



    if (!postindex) {

        tcg_gen_addi_i64(tcg_addr, tcg_addr, offset);

    }



    if (is_vector) {

        if (is_load) {

            do_fp_ld(s, rt, tcg_addr, size);

        } else {

            do_fp_st(s, rt, tcg_addr, size);

        }

    } else {

        TCGv_i64 tcg_rt = cpu_reg(s, rt);

        if (is_load) {

            do_gpr_ld(s, tcg_rt, tcg_addr, size, is_signed, false);

        } else {

            do_gpr_st(s, tcg_rt, tcg_addr, size);

        }

    }

    tcg_gen_addi_i64(tcg_addr, tcg_addr, 1 << size);

    if (is_vector) {

        if (is_load) {

            do_fp_ld(s, rt2, tcg_addr, size);

        } else {

            do_fp_st(s, rt2, tcg_addr, size);

        }

    } else {

        TCGv_i64 tcg_rt2 = cpu_reg(s, rt2);

        if (is_load) {

            do_gpr_ld(s, tcg_rt2, tcg_addr, size, is_signed, false);

        } else {

            do_gpr_st(s, tcg_rt2, tcg_addr, size);

        }

    }



    if (wback) {

        if (postindex) {

            tcg_gen_addi_i64(tcg_addr, tcg_addr, offset - (1 << size));

        } else {

            tcg_gen_subi_i64(tcg_addr, tcg_addr, 1 << size);

        }

        tcg_gen_mov_i64(cpu_reg_sp(s, rn), tcg_addr);

    }

}
