            c->status[1].predictor= (int16_t)bytestream_get_le16(&src);

        }

        c->status[0].step_index= (int16_t)bytestream_get_le16(&src);

        if(st){

            c->status[1].step_index= (int16_t)bytestream_get_le16(&src);

        }

