        if(st) {

            c->status[1].predictor  = (int16_t)AV_RL16(src + 0);

            c->status[1].step_index = src[2];

            src += 4;

        }



        while (src < buf + buf_size) {

            uint8_t v1, v2;

            uint8_t v = *src++;

