{

    VCardResponse *response = NULL;



    switch (status) {

    /* known 7816 response codes */

    case VCARD7816_STATUS_SUCCESS:

        return VCARD_RESPONSE_GET_STATIC(

                    VCARD7816_STATUS_SUCCESS);

    case VCARD7816_STATUS_WARNING:

