        response = vcard_response_new_status(status);

        if (response == NULL) {

            /* couldn't allocate the buffer, return memmory error */

            return VCARD_RESPONSE_GET_STATIC(

                        VCARD7816_STATUS_EXC_ERROR_MEMORY_FAILURE);

        }

    }

    assert(response);

    return response;

}
