static const char *local_mapped_attr_path(FsContext *ctx,

                                          const char *path, char *buffer)

{

    char *dir_name;

    char *tmp_path = g_strdup(path);

    char *base_name = basename(tmp_path);



    /* NULL terminate the directory */

    dir_name = tmp_path;

    *(base_name - 1) = '\0';



