                    "push %%"REG_BP"                        \n\t"

                    YSCALEYUV2RGB1b(%%REGBP, %5)

                    "pxor    %%mm7, %%mm7                   \n\t"

                    /* mm2=B, %%mm4=G, %%mm5=R, %%mm7=0 */

#ifdef DITHER1XBPP

                    "paddusb "BLUE_DITHER"(%5), %%mm2      \n\t"

