                    ++mlz->dic_code_bit;

                    mlz->current_dic_index_max *= 2;

                    mlz->bump_code = mlz->current_dic_index_max - 1;

                } else {

                    if (string_code >= mlz->next_code) {

                        int ret = decode_string(mlz, &buff[output_chars], last_string_code, &char_code, size - output_chars);

