        if(dir!=2 && x>xmin) CHECK_MV4_DIR(x-1, y  , 0)

        if(dir!=3 && y>ymin) CHECK_MV4_DIR(x  , y-1, 1)

        if(dir!=0 && x<xmax) CHECK_MV4_DIR(x+1, y  , 2)

        if(dir!=1 && y<ymax) CHECK_MV4_DIR(x  , y+1, 3)



        if(next_dir==-1){

            return dmin;

        }

    }

}
