		s->rl_chroma_table_index, 

		s->dc_table_index,

		s->mv_table_index,

                s->per_mb_rl_table,

                s->qscale);*/

	if(s->flipflop_rounding){

	    s->no_rounding ^= 1;

	}else{

	    s->no_rounding = 0;

	}

    }

//printf("%d %d %d %d %d\n", s->pict_type, s->bit_rate, s->inter_intra_pred, s->width, s->height);



    s->esc3_level_length= 0;

    s->esc3_run_length= 0;



#ifdef DEBUG

    printf("*****frame %d:\n", frame_count++);

#endif

    return 0;

}
