int v9fs_co_mknod(V9fsState *s, V9fsString *path, uid_t uid,

                  gid_t gid, dev_t dev, mode_t mode)

{

    int err;

    FsCred cred;



    cred_init(&cred);

    cred.fc_uid  = uid;

    cred.fc_gid  = gid;

    cred.fc_mode = mode;

