static inline void qtrle_decode_2n4bpp(QtrleContext *s, int stream_ptr,

                             int row_ptr, int lines_to_change, int bpp)

{

    int rle_code, i;

    int pixel_ptr;

    int row_inc = s->frame.linesize[0];

    unsigned char pi[16];  /* 16 palette indices */

    unsigned char *rgb = s->frame.data[0];

    int pixel_limit = s->frame.linesize[0] * s->avctx->height;

    int num_pixels = (bpp == 4) ? 8 : 16;



    while (lines_to_change--) {

        CHECK_STREAM_PTR(2);

        pixel_ptr = row_ptr + (num_pixels * (s->buf[stream_ptr++] - 1));




        while ((rle_code = (signed char)s->buf[stream_ptr++]) != -1) {

            if (rle_code == 0) {

                /* there's another skip code in the stream */

                CHECK_STREAM_PTR(1);

                pixel_ptr += (num_pixels * (s->buf[stream_ptr++] - 1));


            } else if (rle_code < 0) {

                /* decode the run length code */

                rle_code = -rle_code;

                /* get the next 4 bytes from the stream, treat them as palette

                 * indexes, and output them rle_code times */

                CHECK_STREAM_PTR(4);

                for (i = num_pixels-1; i >= 0; i--) {

                    pi[num_pixels-1-i] = (s->buf[stream_ptr] >> ((i*bpp) & 0x07)) & ((1<<bpp)-1);

                    stream_ptr+= ((i & ((num_pixels>>2)-1)) == 0);

                }

                CHECK_PIXEL_PTR(rle_code * num_pixels);

                while (rle_code--) {

                    for (i = 0; i < num_pixels; i++)

                        rgb[pixel_ptr++] = pi[i];

                }

            } else {

                /* copy the same pixel directly to output 4 times */

                rle_code *= 4;

                CHECK_STREAM_PTR(rle_code);

                CHECK_PIXEL_PTR(rle_code*(num_pixels>>2));

                while (rle_code--) {

                    if(bpp == 4) {

                        rgb[pixel_ptr++] = ((s->buf[stream_ptr]) >> 4) & 0x0f;

                        rgb[pixel_ptr++] = (s->buf[stream_ptr++]) & 0x0f;

                    } else {

                        rgb[pixel_ptr++] = ((s->buf[stream_ptr]) >> 6) & 0x03;

                        rgb[pixel_ptr++] = ((s->buf[stream_ptr]) >> 4) & 0x03;

                        rgb[pixel_ptr++] = ((s->buf[stream_ptr]) >> 2) & 0x03;

                        rgb[pixel_ptr++] = (s->buf[stream_ptr++]) & 0x03;

                    }

                }

            }

        }

        row_ptr += row_inc;

    }

},1,ffmpeg,2d49896e62aa728029697d1d24c8f391

static int ppc_hash32_translate(CPUPPCState *env, struct mmu_ctx_hash32 *ctx,

                                target_ulong eaddr, int rwx)

{

    int ret;

    target_ulong sr;



    /* 1. Handle real mode accesses */

    if (((rwx == 2) && (msr_ir == 0)) || ((rwx != 2) && (msr_dr == 0))) {

        /* Translation is off */

        ctx->raddr = eaddr;

        ctx->prot = PAGE_READ | PAGE_EXEC | PAGE_WRITE;

        return 0;

    }



    /* 2. Check Block Address Translation entries (BATs) */

    if (env->nb_BATs != 0) {

        ret = ppc_hash32_get_bat(env, ctx, eaddr, rwx);

        if (ret == 0) {

            return 0;

        }

    }



    /* 3. Look up the Segment Register */

    sr = env->sr[eaddr >> 28];



    /* 4. Handle direct store segments */

    if (sr & SR32_T) {

        return ppc_hash32_direct_store(env, sr, eaddr, rwx,

                                       &ctx->raddr, &ctx->prot);

    }



    /* 5. Check for segment level no-execute violation */

    ctx->nx = !!(sr & SR32_NX);

    if ((rwx == 2) && ctx->nx) {

        return -3;

    }

    ret = find_pte32(env, ctx, sr, eaddr, rwx);



    return ret;

}
