    c->prefetch = ff_prefetch_arm;

#endif



#if HAVE_IWMMXT

    dsputil_init_iwmmxt(c, avctx);

#endif

#if HAVE_ARMVFP

    ff_float_init_arm_vfp(c, avctx);

#endif

#if HAVE_NEON

    ff_dsputil_init_neon(c, avctx);

#endif

}
