        return;

FF_ENABLE_DEPRECATION_WARNINGS

#endif /* FF_API_XVMC */



    if (INLINE_SSE(cpu_flags)) {

        c->clear_block  = clear_block_sse;

        c->clear_blocks = clear_blocks_sse;

    }

#endif /* HAVE_INLINE_ASM */

}
