void net_slirp_smb(const char *exported_dir)

{

    struct in_addr vserver_addr = { .s_addr = 0 };



    if (legacy_smb_export) {

        fprintf(stderr, "-smb given twice\n");

        exit(1);

    }

    legacy_smb_export = exported_dir;

