		dst[1]= palette[ src[i]*4+2 ];

		#else

		//FIXME slow?

		dst[0]= palette[ src[i]*4+0 ];

		dst[1]= palette[ src[i]*4+1 ];

		dst[2]= palette[ src[i]*4+2 ];

//		dst[3]= 0; /* do we need this cleansing? */

		#endif



		dst+= 4;

	}

}
